package calc

import (
	"errors"
	"strconv"
)

// ErrEmpty is returned by Len for an empty string.
var ErrEmpty = errors.New("empty")

// Parse converts s to an int. DEPRECATED — remove it.
func Parse(s string) (int, error) {
	return strconv.Atoi(s)
}

// Len returns the length of s, or ErrEmpty when s is empty.
func Len(s string) (int, error) {
	if s == "" {
		return 0, ErrEmpty
	}
	return len(s), nil
}

package calc

import (
	"errors"
	"testing"
)

func TestLen(t *testing.T) {
	if n, err := Len("abc"); err != nil || n != 3 {
		t.Fatalf("Len(abc) = (%d, %v), want (3, nil)", n, err)
	}
	if _, err := Len(""); !errors.Is(err, ErrEmpty) {
		t.Fatalf("Len(\"\") err = %v, want ErrEmpty", err)
	}
}

